import { readFile } from "node:fs/promises";
import { RunScope } from "@lab/shared/schemas";

const [command, file] = process.argv.slice(2);
if (command !== "check" || !file) {
  console.error("usage: lab-worker check <scope.json>");
  process.exit(2);
}
const result = RunScope.safeParse(JSON.parse(await readFile(file, "utf8")));
console.log(result.success ? `ok: ${result.data.repo} ${result.data.branch}` : `bad scope: ${result.error.issues.length} problem(s)`);
process.exitCode = result.success ? 0 : 1;

import { createSdkMcpServer, type Options, type SessionStore } from "@anthropic-ai/claude-agent-sdk/core";

